#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* I'll implement a basic compressor that mirrors decomp logic */

int cc[1000000];  /* context counts */
int radix = 255;
long low = 0;
long high = (1L << 31) - 1;
long range;
int pending = 0;
int bits_written = 0;

struct BitWriter {
  unsigned char *buf;
  int byte_pos;
  int bit_pos;
};

struct BitWriter bw = {.buf = malloc(10000), .byte_pos = 0, .bit_pos = 0};

void write_bit(int bit) {
  if (bw.bit_pos == 0) {
    bw.buf[bw.byte_pos] = 0;
  }
  if (bit) {
    bw.buf[bw.byte_pos] |= (1 << (7 - bw.bit_pos));
  }
  bw.bit_pos++;
  if (bw.bit_pos == 8) {
    bw.bit_pos = 0;
    bw.byte_pos++;
  }
}

void put_bit(int ctx, int bit) {
  int *counts = cc + ctx * 2;
  range = high - low + 1;
  long split = low + (range * (counts[0] + 1)) / (counts[0] + counts[1] + 2);

  if (bit) {
    low = split + 1;
    counts[1]++;
  } else {
    high = split;
    counts[0]++;
  }

  while ((high ^ low) < (1L << 30)) {
    write_bit((low >> 30) & 1);
    low <<= 1;
    high = (high << 1) | 1;
  }
}

void put_integer(int val, int nbits, int ctx) {
  int subtract_it = 1 << nbits;
  val += subtract_it;

  ctx *= 99;
  int len = 31 - __builtin_clz(val);

  for (int j = nbits; j < len; j++) {
    put_bit(j + 1 + ctx, 0);
  }
  put_bit(len + ctx, 1);

  for (int j = len - 1; j >= 0; j--) {
    put_bit(ctx, (val >> j) & 1);
  }
}

int main() {
  char buf[10000];
  int len = 0;
  int c;

  while ((c = getchar()) != EOF) {
    buf[len++] = c;
  }

  memset(cc, 0, sizeof(cc));
  low = 0;
  high = (1L << 31) - 1;

  put_integer(len, 9, 0);

  for (int i = 0; i < len; i++) {
    unsigned char ch = (unsigned char)buf[i];
    put_bit(1, 0);  /* literal, not a match */

    int sign = (ch < 128) ? 0 : 1;
    put_bit(8, sign);

    int val = sign ? (256 - ch) : ch;

    for (int j = 3; j >= 0; j--) {
      put_bit(9, (val >> j) & 1);
    }
  }

  /* Flush remaining bits */
  for (int i = 0; i < 32; i++) {
    write_bit((low >> (30 - i)) & 1);
  }

  fwrite(bw.buf, 1, bw.byte_pos + (bw.bit_pos > 0 ? 1 : 0), stdout);
  return 0;
}
