#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Arithmetic coder to match decomp.c */
int cc[1000000];
int radix = 255;
long fraction = 0;
long range = 1;

unsigned char output[10000];
int output_pos = 0;

void put_bit(int ctx, int bit) {
  if (range < radix) {
    range *= radix;
    fraction *= radix;
    fraction += radix - 1;  /* Read a byte worth 254 on input side */
  }

  int *counts = cc + ctx * 2;
  /* split = range * (counts[0] + 1) / (counts[0] + counts[1] + 2) */
  long split = range * (counts[0] + 1) / (counts[0] + counts[1] + 2);

  if (bit) {
    fraction -= split;
    range -= split;
    counts[1]++;
  } else {
    range = split;
    counts[0]++;
  }
}

void put_integer(int val, int nbits, int ctx) {
  /* Inverse of get_integer: 
     get_integer returns val - (1<<nbits)
     So to encode val, we send val + (1<<nbits)
  */
  int subtract_it = 1 << nbits;
  int to_send = val + subtract_it;

  ctx *= 99;

  /* Find how many bits we need */
  int bit_len = 0;
  int temp = to_send;
  while (temp > 0) {
    temp >>= 1;
    bit_len++;
  }

  /* Send unary code for bit length */
  for (int j = nbits; j < bit_len; j++) {
    put_bit(j + 1 + ctx, 0);
  }
  put_bit(bit_len + ctx, 1);

  /* Send the value bits */
  for (int j = bit_len - 1; j >= 0; j--) {
    put_bit(ctx, (to_send >> j) & 1);
  }
}

int main() {
  char buf[10000];
  int len = 0;
  int c;

  while ((c = getchar()) != EOF && len < sizeof(buf)) {
    buf[len++] = c;
  }

  memset(cc, 0, sizeof(cc));
  fraction = 0;
  range = 1;

  /* Send length */
  put_integer(len, 9, 0);

  /* Send all as literals */
  for (int i = 0; i < len; i++) {
    unsigned char ch = (unsigned char)buf[i];

    /* 0 = literal */
    put_bit(1, 0);

    /* Sign bit: 1 if ch >= 128 */
    int sign_bit = (ch >= 128) ? 1 : 0;
    put_bit(8, sign_bit);

    /* Value: magnitude in 4 bits */
    int val = sign_bit ? (ch - 128) : ch;
    val = (val >> 4) & 0xF;  /* top 4 bits */

    for (int j = 3; j >= 0; j--) {
      put_bit(9, (val >> j) & 1);
    }
  }

  /* Flush: write out remaining fraction */
  while (fraction > 0 && output_pos < sizeof(output)) {
    output[output_pos++] = (unsigned char)(fraction & 0xFF);
    fraction >>= 8;
  }

  fwrite(output, 1, output_pos, stdout);
  return 0;
}
