  long range = high - low;
  long split = low + range * (counts[0] + 1) / (counts[0] + counts[1] + 2);

  if (bit) {
    low = split + 1;
    counts[1]++;
  } else {
    high = split;
    counts[0]++;
  }

  /* Emit bytes when high bytes are the same */
  while ((low ^ high) < 0x01000000UL) {
    out[outlen++] = (low >> 24) + 1;
    low = (low << 8);
    high = (high << 8) | 0xFF;
  }
}

