  int to_send = val + subtract_it;
  ctx *= 99;
  int len = 0, temp = to_send;
  while (temp > 0) { temp >>= 1; len++; }
  if (len == 0) len = 1;
  for (int j = nbits; j < len; j++) put_bit(j + 1 + ctx, 0);
  put_bit(len + ctx, 1);
  for (int j = len - 1; j >= 0; j--) put_bit(ctx, (to_send >> j) & 1);
}

