  char buf[10000];
  int len = 0, c;
  while ((c = getchar()) != EOF && len < 10000) buf[len++] = c;

  memset(cc, 0, sizeof(cc));
  low = 0; high = 0xFFFFFFFFUL;

  put_integer(len, 9, 0);

  for (int i = 0; i < len; i++) {
    unsigned char ch = (unsigned char)buf[i];
    put_bit(1, 0);
    int sign_bit = (ch < 128) ? 0 : 1;
