#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* 
   Key insight from tracing:
   - Initial: range=1, fraction=0
   - When get_bit is called and range < 255:
     - range *= 255, fraction *= 255
     - byte = gc(), fraction += (byte - 1)

   So if I want to emit bytes that encode specific bits:
   - I need to track what fraction/range state the decoder will be in
   - Then emit bytes accordingly

   The decoder's get_bit logic:
   - If byte=255: fraction becomes 0*255 + 254 = 254
   - split = range * (counts[0] + 1) / (counts[0] + counts[1] + 2)
   - Initial counts[0]=1, counts[1]=0, so split = range * 1 / 2
   - bit = (fraction >= split)

   So with fraction=254 and range=255:
   - split = 255 * 1 / 2 = 127
   - bit = (254 >= 127) = 1

   This means byte 255 always produces bit 1 (initially).

   What if I want bit 0?
   - Need fraction < split = 127
   - If range=255, split=127, need fraction < 127
   - After reading byte B: fraction = 0 * 255 + (B - 1) = B - 1
   - So need B - 1 < 127, i.e., B < 128
   - Byte 128 gives fraction=127, which is NOT < 127, so bit 1
   - Byte 127 gives fraction=126, which is < 127, so bit 0
*/

int cc[1000000];
int radix = 255;
int fraction = 0;
long range = 1;
unsigned char out[10000];
int outlen = 0;

void put_bit(int ctx, int bit) {
  fprintf(stderr, "put_bit(ctx=%d, bit=%d): before: range=%ld, fraction=%d\n", ctx, bit, range, fraction);

  if (range < radix) {
    range *= radix;
    fraction *= radix;
    fraction += radix - 1;
    fprintf(stderr, "  expanded: range=%ld, fraction=%d\n", range, fraction);
  }

  int *counts = cc + ctx * 2;
  long split = (long)range * (counts[0] + 1) / (counts[0] + counts[1] + 2);

  if (bit) {
    fraction -= split;
    range -= split;
    counts[1]++;
  } else {
    range = split;
    counts[0]++;
  }

  fprintf(stderr, "  after: range=%ld, fraction=%d, split=%ld\n", range, fraction, split);
}

int main() {
  memset(cc, 0, sizeof(cc));
  fraction = 0;
  range = 1;

  /* Simulate putting bits and track state */
  fprintf(stderr, "=== Putting bit 1 with ctx=10 ===\n");
  put_bit(10, 1);

  fprintf(stderr, "\n=== Now we have range=%ld, fraction=%d ===\n", range, fraction);
  fprintf(stderr, "=== Decoder will read a byte ===\n");
  fprintf(stderr, "If we emit byte 255:\n");
  fprintf(stderr, "  Decoder: range=255*255=65025, fraction=254*255+254=%d\n", 254*255+254);
  fprintf(stderr, "  split = 65025 * 1 / 2 = %ld\n", 65025L / 2);

  return 0;
}
