    put_bit(8, sign_bit);
    int val = (ch < 128) ? ch : (256 - ch);
    if (val > 15) val = 15;
    for (int j = 3; j >= 0; j--) put_bit(9, (val >> j) & 1);
  }

  for (int i = 0; i < 4 && outlen < sizeof(out) - 1; i++) {
